// Chega da saída de erro de qualquer nó entre a reserva e o laço de criação. Só o texto do erro segue adiante.
const input = $input.first().json;
const raw = input.error ?? input.message ?? 'erro desconhecido';
const message = String(typeof raw === 'string' ? raw : raw?.message ?? JSON.stringify(raw)).slice(0, 300);
const batchId = $('RESERVAR PROXIES (API)').first().json.batchId;
if (!batchId) throw new Error('Lote sem identificador: não foi possível liberar. Motivo da falha: ' + message);
return [{ json: { batchId, errorMessage: message } }];

const failure = $('PREPARAR LIBERAÇÃO DO LOTE').first().json;
const response = $input.first().json;
const status = Number(response.statusCode);
const released = status === 200 ? Number(response.body?.released ?? 0) : null;
const mensagem = 'Nenhum perfil foi criado: ' + failure.errorMessage + ' ' +
  (released === null ? 'ATENÇÃO: não foi possível liberar as proxies reservadas (a Central respondeu ' + (Number.isFinite(status) ? status : 'sem resposta') + '); elas voltam sozinhas em até 15 minutos.'
    : 'Reservas desfeitas: ' + released + ' (proxies livres e numeração preservada).');
return [{ json: { titulo: 'Falha — nenhum perfil criado', mensagem, liberacaoDoLote: released === null ? 'FALHOU' : 'OK', reservasDesfeitas: released } }];

const input = $input.first();
const binaries = input.binary ?? {};

return Object.entries(binaries).map(([fieldName, file]) => ({
  json: {
    fileName: file.fileName ?? fieldName,
    originalBinaryField: fieldName
  },
  binary: {
    data: file
  }
}));

const text = String($json.content ?? '');
const source = $('SEPARA PERFIS').item.json;
const fileName = source.fileName ?? null;

// =============================================
// 1. NORMALIZAÇÃO
// =============================================

const normalized = text
  .replace(/\r/g, '')
  .replace(/\u00A0/g, ' ')
  .trim();

const lines = normalized
  .split('\n')
  .map(line => line.trim())
  .filter(Boolean);

function cleanLabel(value) {
  return String(value ?? '')
    .replace(/\*\*/g, '')
    .replace(/#+/g, '')
    .trim();
}

function normalizeLabel(value) {
  return cleanLabel(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function filled(value) {
  return value !== null &&
    value !== undefined &&
    String(value).trim() !== '';
}

function afterColon(line) {
  const index = line.indexOf(':');

  if (index === -1) return null;

  return line.slice(index + 1).trim() || null;
}

function nextValue(index) {
  const next = lines[index + 1];

  if (!next) return null;

  // Não consumir outra etiqueta como valor.
  if (/^[\wÀ-ÿ /-]+\s*:/.test(next)) {
    return null;
  }

  return next;
}

function valueFromLabel(index) {
  return afterColon(lines[index]) ??
    nextValue(index);
}

function detectProvider(email) {
  if (!email) return null;

  const value = email.toLowerCase();

  if (
    /@(outlook|hotmail|live)\./.test(value)
  ) {
    return 'outlook';
  }

  if (/@gmail\./.test(value)) {
    return 'gmail';
  }

  return 'other';
}

function cleanTwoFactor(value) {
  if (!filled(value)) return null;

  return String(value)
    .replace(/\s+/g, '')
    .trim() || null;
}

// =============================================
// 2. ESTRUTURA DE SAÍDA
// =============================================

const result = {
  source: {
    fileName
  },

  person: {
    name: null
  },

  facebook: {
    url: null,
    id: null,
    login: null,
    password: null,
    loginSource: null
  },

  email: {
    provider: null,
    login: null,
    password: null
  },

  twoFactor: {
    current: null,
    new: null
  },

  recoveryCodes: [],

  document: {
    present: false,
    url: null
  },

  cookies: {
    present: false,
    count: 0,
    data: null
  },

  review: {
    required: false,
    reasons: []
  }
};

// =============================================
// 3. NOME DA PESSOA
// =============================================

const reservedLabels = [
  'facebook',
  'outlook',
  'email',
  'e-mail',
  'login',
  'senha',
  'login face/email',
  'senha face/email',
  'login facebook/email',
  'senha facebook/email',
  '2fa',
  '2fa novo',
  '2fa- key',
  '2fa - key',
  'codigo reserva',
  'codigo de reserva',
  'id do perfil',
  'url'
];

for (const line of lines) {
  const cleaned = cleanLabel(line);
  const label = normalizeLabel(cleaned);

  const isReserved = reservedLabels.some(
    reserved => label === reserved
  );

  const isUrl = /^https?:\/\//i.test(cleaned);
  const isNumeric = /^\d+$/.test(cleaned);
  const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleaned);
  const isField = cleaned.includes(':');

  if (
    !isReserved &&
    !isUrl &&
    !isNumeric &&
    !isEmail &&
    !isField
  ) {
    result.person.name = cleaned
      .replace(/^📄\s*/, '')
      .trim();

    break;
  }
}

// =============================================
// 4. URL E ID DO FACEBOOK
// =============================================

const facebookUrl = normalized.match(
  /https?:\/\/(?:www\.)?facebook\.com\/[^\s]+/i
);

if (facebookUrl) {
  result.facebook.url = facebookUrl[0];

  const idMatch = facebookUrl[0].match(
    /[?&]id=(\d+)/i
  );

  if (idMatch) {
    result.facebook.id = idMatch[1];
  }
}

// ID numérico em linha separada
if (!result.facebook.id) {
  const idLine = lines.find(line =>
    /^\d{10,20}$/.test(line)
  );

  if (idLine) {
    result.facebook.id = idLine;
  }
}

// =============================================
// 5. DOCUMENTO
// =============================================

const documentMatch = normalized.match(
  /https?:\/\/i\.postimg\.cc\/[^\s]+?\.(?:png|jpg|jpeg|webp)/i
);

if (documentMatch) {
  result.document.present = true;
  result.document.url = documentMatch[0];
}

// =============================================
// 6. CREDENCIAIS
// =============================================

let section = null;

for (let i = 0; i < lines.length; i++) {
  const original = lines[i];
  const label = normalizeLabel(original);

  // Seções
  if (label === 'facebook') {
    section = 'facebook';
    continue;
  }

  if (label === 'outlook' ||
      label === 'email' ||
      label === 'e-mail') {
    section = 'email';
    continue;
  }

  // Login compartilhado explícito
  if (
    /^login (face|facebook)\/(email|e-mail)\s*:?\s*/.test(label)
  ) {
    const value = valueFromLabel(i);

    if (filled(value)) {
      result.facebook.login = value;
      result.facebook.loginSource = 'SHARED_EXPLICIT';
      result.email.login = value;
    }

    continue;
  }

  // Senha compartilhada explícita
  if (
    /^senha (face|facebook)\/(email|e-mail)\s*:?\s*/.test(label)
  ) {
    const value = valueFromLabel(i);

    if (filled(value)) {
      result.facebook.password = value;
      result.email.password = value;
    }

    continue;
  }

  // FB: login : senha
  if (
    label.startsWith('fb:') ||
    label.startsWith('facebook:')
  ) {
    const raw = afterColon(original);

    if (!raw) continue;

    const parts = raw.split(/\s+:\s+/);

    result.facebook.login = parts[0]?.trim() || null;
    result.facebook.loginSource = 'FACEBOOK_EXPLICIT';

    if (parts.length > 1) {
      result.facebook.password =
        parts.slice(1).join(' : ').trim();
    }

    continue;
  }

  // E-mail: login : senha
  if (
    label.startsWith('email:') ||
    label.startsWith('e-mail:') ||
    label.startsWith('outlook:')
  ) {
    const raw = afterColon(original);

    if (!raw) {
      const value = nextValue(i);

      if (filled(value)) {
        result.email.login = value;
      }

      continue;
    }

    const parts = raw.split(/\s+:\s+/);

    result.email.login = parts[0]?.trim() || null;

    if (parts.length > 1) {
      result.email.password =
        parts.slice(1).join(' : ').trim();
    }

    continue;
  }

  // Login em seção
  if (label.startsWith('login:')) {
    const value = valueFromLabel(i);

    if (section === 'facebook') {
      result.facebook.login = value;
      result.facebook.loginSource = 'FACEBOOK_SECTION';
    } else if (section === 'email') {
      result.email.login = value;
    }

    continue;
  }

  // Senha em seção ou genérica
  if (label.startsWith('senha:')) {
    const value = valueFromLabel(i);

    if (section === 'facebook') {
      result.facebook.password = value;
    } else if (section === 'email') {
      result.email.password = value;
    } else {
      // Senha genérica: não presumir destino Facebook.
      result.email.password ??= value;
    }

    continue;
  }

  // 2FA novo
  if (
    /^2fa novo\s*:/.test(label) ||
    label === '2fa novo'
  ) {
    result.twoFactor.new =
      cleanTwoFactor(valueFromLabel(i));

    continue;
  }

  // 2FA atual
  if (
    /^2fa\s*:/.test(label) ||
    label === '2fa' ||
    /^2fa\s*-\s*key\s*:?\s*/.test(label)
  ) {
    result.twoFactor.current =
      cleanTwoFactor(valueFromLabel(i));

    continue;
  }
}

// =============================================
// 7. REGRAS DE AMBIGUIDADE
// =============================================

// Alguns TXT possuem apenas EMAIL e SENHA.
// Preservamos o e-mail sem assumir que ele
// também seja o login Facebook.
if (
  !result.facebook.login &&
  result.email.login
) {
  result.review.required = true;
  result.review.reasons.push(
    'Login Facebook não identificado explicitamente.'
  );
}

if (
  result.facebook.login &&
  !result.facebook.password
) {
  result.review.required = true;
  result.review.reasons.push(
    'Senha Facebook não identificada.'
  );
}

result.email.provider =
  detectProvider(result.email.login);

// =============================================
// 8. CÓDIGOS DE RECUPERAÇÃO
// =============================================

const recoveryIndex = lines.findIndex(line => {
  const label = normalizeLabel(line);

  return (
    label.startsWith('codigo reserva') ||
    label.startsWith('codigo de reserva')
  );
});

if (recoveryIndex !== -1) {
  for (
    let i = recoveryIndex + 1;
    i < lines.length;
    i++
  ) {
    const line = lines[i];

    if (
      /^https?:\/\//i.test(line) ||
      /[A-Za-z]/.test(line)
    ) {
      break;
    }

    const codes = line.match(
      /\d{4}\s+\d{4}/g
    );

    if (codes) {
      result.recoveryCodes.push(...codes);
    }
  }
}

// =============================================
// 9. COOKIES
// =============================================

const jsonStart = normalized.indexOf('[{');

if (jsonStart !== -1) {
  const possibleJson = normalized.slice(jsonStart);

  try {
    const parsed = JSON.parse(possibleJson);

    if (Array.isArray(parsed)) {
      result.cookies.present = parsed.length > 0;
      result.cookies.count = parsed.length;
      result.cookies.data = parsed;
    }
  } catch {
    result.review.required = true;
    result.review.reasons.push(
      'Cookies encontrados, mas JSON inválido.'
    );
  }
}

// =============================================
// 10. VALIDAÇÃO
// =============================================

result.validation = {
  facebookLoginFound:
    Boolean(result.facebook.login),

  facebookPasswordFound:
    Boolean(result.facebook.password),

  emailFound:
    Boolean(result.email.login),

  emailPasswordFound:
    Boolean(result.email.password),

  twoFactorFound:
    Boolean(
      result.twoFactor.current ||
      result.twoFactor.new
    ),

  cookiesFound:
    result.cookies.present,

  documentFound:
    result.document.present
};

return result;

// Separa os TXT aptos dos que precisam de revisão. Nenhuma credencial segue adiante: só metadados.
const API_BASE = 'https://host.docker.internal:7090'; // endereço da Central visto de dentro do Docker; troque ao publicar
const TARGET_PLATFORM = 'ESTEIRA DE PERFIL';
const items = $input.all();
const profiles = items.filter(item => item.json.source?.fileName && item.json.facebook && item.json.validation);
if (!profiles.length) throw new Error('Nenhum TXT recebido.');
const names = profiles.map(item => String(item.json.source.fileName).trim().toLowerCase());
if (new Set(names).size !== names.length) throw new Error('Arquivos TXT duplicados no lote.');
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16); });
const valid = [], review = [];
profiles.forEach((item, index) => {
  const p = item.json;
  const facebookIdentifier = String(p.facebook?.login ?? '').trim();
  const reasons = [...(p.review?.reasons ?? [])];
  if (!facebookIdentifier) reasons.push('Login Facebook ausente.');
  if (!p.facebook?.password) reasons.push('Senha Facebook ausente.');
  const unique = [...new Set(reasons)];
  if (p.review?.required || unique.length) { review.push({ sourceFile: p.source.fileName, sourceItemIndex: index, reasons: unique }); return; }
  valid.push({
    sourceFile: p.source.fileName, sourceItemIndex: index, facebookIdentifier, emailIdentifier: String(p.email?.login ?? '').trim(),
    facebookAccountPresent: true, emailAccountPresent: Boolean(p.email?.login && p.email?.password), twoFactorPresent: Boolean(p.twoFactor?.current),
    cookiesPresent: Boolean(p.cookies?.present), cookiesCount: Number(p.cookies?.count ?? 0), documentPresent: Boolean(p.document?.present),
  });
});
console.log(JSON.stringify({ received: profiles.length, ready: valid.length, reviewRequired: review.length }));
if (!valid.length) throw new Error('Nenhum perfil apto para provisionamento. Verifique os arquivos pendentes de revisão.');
// A chave de idempotência acompanha o item: repetir a chamada (retry) devolve a mesma reserva, sem consumir outra proxy.
return [{ json: { apiBase: API_BASE, idempotencyKey: uuid(), count: valid.length, platform1: TARGET_PLATFORM, valid, review } }];

const reservation = $input.first().json;
const plan = $('CLASSIFICAR PERFIS').first().json;
if (!reservation || !Array.isArray(reservation.items) || typeof reservation.reserved !== 'number') throw new Error('Resposta inesperada da API da Central.');
if (reservation.requested !== plan.count) throw new Error('A API atendeu um pedido de tamanho diferente do enviado.');
const group = reservation.group;
if (!group?.id || !['Test', 'Production'].includes(group.mode)) throw new Error('A API não informou o grupo de ingestão do AdsPower.');
if (reservation.reserved === 0) {
  const motivo = reservation.pending?.[0]?.message ?? 'Falta de proxy disponível.';
  throw new Error('Nenhum perfil foi preenchido (' + plan.count + ' solicitado(s)): ' + motivo + ' Arquivos: ' + plan.valid.map(v => v.sourceFile).join(', '));
}
if (reservation.items.length > plan.valid.length) throw new Error('A API devolveu mais reservas do que perfis válidos.');
// Menor número primeiro: o primeiro TXT válido recebe a primeira reserva, e assim por diante.
return reservation.items.map((item, index) => {
  const entry = plan.valid[index];
  const proxy = item.proxy;
  if (!proxy?.host || !proxy?.port || !proxy?.username || !proxy?.password) throw new Error('Reserva sem conexão de proxy para ' + item.profileName + '.');
  return { json: {
    batchItemId: item.profileName + '-' + item.allocationId, profileName: item.profileName, profileNumber: item.profileNumber,
    allocationId: item.allocationId, reservationExpiresAt: item.reservationExpiresAt, groupId: String(group.id), groupName: group.name, environment: group.mode, ...entry,
    proxy: { host: String(proxy.host), port: Number(proxy.port), username: String(proxy.username), password: String(proxy.password) },
    status: 'READY_FOR_CREATION' } };
});

const filled = value => value !== null && value !== undefined && String(value).trim() !== '';
return $input.all().map(item => {
  const data = item.json;
  // O grupo vem da Central: teste (FB Teste | YAGO) ou produção (03 ESTEIRA DE PERFIL). Nunca é fixo no fluxo.
  if (!filled(data.groupId) || !['Test', 'Production'].includes(data.environment)) throw new Error('Grupo de ingestão do AdsPower ausente.');
  if (data.status !== 'READY_FOR_CREATION') throw new Error('Perfil sem reserva de proxy.');
  if (!filled(data.facebookIdentifier)) throw new Error('Identificador Facebook ausente.');
  const p = data.proxy;
  if (!filled(p?.host) || !filled(p?.port) || !filled(p?.username) || !filled(p?.password)) throw new Error('Configuração de proxy incompleta.');
  const port = Number(p.port);
  if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error('Porta de proxy inválida.');
  const remark = ['━━━ PERFIL | ESTEIRA ━━━', '', 'PÁGINA |', '', 'DADOS', 'EMAIL: ' + (data.emailIdentifier ?? ''), 'SENHA:', '2FA:', '', 'BMs', '', 'MOVIMENTOS'].join('\n');
  const payload = {
    name: String(data.profileName).trim(), group_id: String(data.groupId), domain_name: 'facebook.com', username: String(data.facebookIdentifier).trim(), remark,
    user_proxy_config: { proxy_soft: 'other', proxy_type: 'http', proxy_host: String(p.host).trim(), proxy_port: String(port), proxy_user: String(p.username), proxy_password: String(p.password) },
    fingerprint_config: { automatic_timezone: '1', language: ['pt-BR', 'pt'], webrtc: 'disabled', random_ua: { ua_browser: ['chrome'], ua_system_version: ['Windows 10', 'Windows 11'] } },
  };
  return { json: { batchItemId: data.batchItemId, profileName: data.profileName, allocationId: data.allocationId, groupId: String(data.groupId), groupName: data.groupName, environment: data.environment, status: 'PAYLOAD_PREPARED', payload } };
});

const responses = $input.all();
const preparedItems = $('PREPARAR ADSPOWER').all();
const groupId = String($('RESERVAR PROXIES (API)').first().json.group?.id ?? '');
if (!groupId) throw new Error('A API não informou o grupo de ingestão do AdsPower.');
if (responses.length !== 1) throw new Error('Esperada uma consulta AdsPower, recebidas ' + responses.length + '.');
const response = responses[0].json;
if (response.code !== 0) throw new Error('Consulta AdsPower falhou (code ' + response.code + ': ' + String(response.msg ?? response.message ?? 'sem mensagem').slice(0, 200) + '). Se for limite de chamadas por segundo, aguarde alguns segundos; se for chave, confira a credencial nos nós do AdsPower.');
const data = response.data;
if (!data || !Array.isArray(data.list)) throw new Error('Resposta inválida do AdsPower.');
const page = Number(data.page), pageSize = Number(data.page_size);
if (page !== 1 || !Number.isInteger(pageSize) || pageSize < 1) throw new Error('Paginação inesperada.');
if (data.list.length >= pageSize) throw new Error('Consulta pode ter mais páginas. Não é seguro autorizar criação.');
if (!preparedItems.length) throw new Error('Nenhum perfil preparado.');
const existingNames = new Set(data.list.map(profile => String(profile.name ?? '').trim().toLowerCase()));
const batchNames = new Set();
return preparedItems.map(item => {
  const prepared = item.json;
  if (String(prepared.groupId) !== groupId || prepared.status !== 'PAYLOAD_PREPARED') throw new Error('Perfil inválido: ' + prepared.profileName);
  const name = String(prepared.profileName ?? '').trim();
  if (!name) throw new Error('Nome de perfil ausente.');
  const key = name.toLowerCase();
  if (batchNames.has(key)) throw new Error('Nome duplicado dentro do lote: ' + name);
  batchNames.add(key);
  if (existingNames.has(key)) throw new Error('Perfil já existe no AdsPower: ' + name + ' (as reservas vencem sozinhas em 15 minutos).');
  return { json: { batchItemId: prepared.batchItemId, profileName: name, allocationId: prepared.allocationId, groupId, existingProfilesChecked: data.list.length, duplicateFound: false, status: 'READY_FOR_CREATION' } };
});

const current = $input.first().json;
const prepared = $('PREPARAR ADSPOWER').all().find(item => item.json.batchItemId === current.batchItemId)?.json;
if (!prepared?.payload || prepared.profileName !== current.profileName) throw new Error('Payload não encontrado para ' + current.profileName + '.');
return [{ json: { ...current, payload: prepared.payload, status: 'PAYLOAD_READY' } }];

// O AdsPower responde HTTP 200 mesmo quando recusa; só code 0 com id conta como criado.
const response = $input.first().json;
const current = $('OBTER PAYLOAD').last().json;
const ok = response.code === 0 && Boolean(response.data?.id);
return [{ json: {
  ok, allocationId: current.allocationId, profileName: current.profileName, batchItemId: current.batchItemId,
  adsPowerId: ok ? String(response.data.id) : null,
  serialNumber: ok && response.data.serial_number != null ? String(response.data.serial_number) : null,
  reason: ok ? null : /too many|per second|rate/i.test(String(response.msg ?? response.message ?? '')) ? 'ADSPOWER_RATE_LIMIT' : 'ADSPOWER_REJECTED',
  adsPowerCode: response.code ?? null,
  adsPowerMessage: ok ? null : String(response.msg ?? response.message ?? '').slice(0, 300),
} }];

// Chega da recusa do AdsPower (item completo) ou da falha de conexão (item de erro): em ambos, identifica a reserva a liberar.
const input = $input.first().json;
const current = input.allocationId ? input : $('OBTER PAYLOAD').last().json;
// Só o texto de erro do AdsPower/n8n (nunca o corpo enviado), limitado a 300 caracteres.
const detail = input.adsPowerMessage ?? input.error?.message ?? input.message ?? null;
return [{ json: { ok: false, allocationId: current.allocationId, profileName: current.profileName, batchItemId: current.batchItemId, reason: input.reason ?? 'ADSPOWER_UNREACHABLE', adsPowerCode: input.adsPowerCode ?? null, adsPowerMessage: detail === null ? null : String(detail).slice(0, 300) } }];

const safe = name => { try { return $(name).all().map(item => item.json); } catch (error) { return []; } };
const plan = $('CLASSIFICAR PERFIS').first().json;
const reservation = $('RESERVAR PROXIES (API)').first().json;
const registered = safe('REGISTRAR CRIAÇÃO').filter(item => item.ok);
const confirmations = safe('CONFIRMAR NA API');
const failures = safe('PREPARAR LIBERAÇÃO');
const releases = safe('LIBERAR NA API');
const created = registered.map((item, index) => {
  const status = Number(confirmations[index]?.statusCode);
  return { perfil: item.profileName, adsPowerId: item.adsPowerId, serie: item.serialNumber, confirmadoNaCentral: status === 204,
    aviso: status === 204 ? null : 'Perfil criado no AdsPower, mas a Central respondeu ' + (Number.isFinite(status) ? status : 'sem resposta') + ' ao confirmar. Confira a reserva ' + item.allocationId + '.' };
});
const failed = failures.map((item, index) => {
  const status = Number(releases[index]?.statusCode);
  return { perfil: item.profileName, motivo: item.reason, codigoAdsPower: item.adsPowerCode ?? null, mensagemAdsPower: item.adsPowerMessage ?? null, proxyLiberada: status === 204 };
});
// Os TXT válidos que não receberam reserva (falta de proxy) vêm depois dos atendidos, na ordem do pedido.
const unfilled = (reservation.pending ?? []).map((pending, index) => ({ arquivo: plan.valid[reservation.reserved + index]?.sourceFile ?? null, posicao: pending.position, motivo: pending.reason, mensagem: pending.message }));
const review = plan.review ?? [];
const parts = ['Criados ' + created.filter(c => c.confirmadoNaCentral).length + ' de ' + plan.count + ' perfil(is) válido(s) no grupo "' + (reservation.group?.name ?? '?') + '" (' + (reservation.group?.mode === 'Production' ? 'produção' : 'teste') + ').'];
if (unfilled.length) parts.push(unfilled.length + ' não foi(ram) preenchido(s) por falta de proxy disponível: ' + unfilled.map(u => u.arquivo).join(', ') + '.');
if (failed.length) parts.push(failed.length + ' falhou(aram) ao criar no AdsPower (proxy liberada): ' + failed.map(f => f.perfil + (f.mensagemAdsPower ? ' [' + f.mensagemAdsPower + ']' : '')).join(', ') + '.');
if (created.some(c => !c.confirmadoNaCentral)) parts.push('Atenção: há perfil criado no AdsPower sem confirmação na Central.');
if (review.length) parts.push(review.length + ' arquivo(s) precisam de revisão manual: ' + review.map(r => r.sourceFile).join(', ') + '.');
const target = reservation.group ?? {};
return [{ json: {
  grupo: { nome: target.name ?? null, ambiente: target.mode ?? null },
  titulo: unfilled.length || failed.length || review.length ? 'Concluído com pendências' : 'Concluído',
  mensagem: parts.join(' '),
  resumo: { solicitados: plan.count, reservados: reservation.reserved, criados: created.length, falhasNoAdsPower: failed.length, naoPreenchidosPorFaltaDeProxy: unfilled.length, arquivosParaRevisao: review.length },
  criados: created, falhas: failed, naoPreenchidos: unfilled, revisaoManual: review,
} }];

const raw = $input.first().json.error ?? $input.first().json.message ?? 'erro desconhecido';
const message = String(typeof raw === 'string' ? raw : raw?.message ?? JSON.stringify(raw)).slice(0, 300);
return [{ json: { titulo: 'Falha — nenhum perfil criado', mensagem: 'Nenhum perfil foi criado: ' + message + ' Nenhuma proxy foi reservada.', reservasDesfeitas: 0 } }];
